content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-09-weather-care-006

=== 用户原始指令 (query.txt) ===
弄个一行带数字的显示 点跳应用 读天气 那种快不行的提醒也要有

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个一行带数字的显示 点跳应用 读天气 那种快不行的提醒也要有",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "区或县名称，用于标识当前天气所在地区。",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "36°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "alertLevel": {
            "type": "string",
            "description": "当前天气预警信息。",
            "sampleValue": "高温橙色预警"
          }
        },
        "updatedAt": {
          "type": "string",
          "description": "端侧完成天气查询和归一化的更新时间。",
          "sampleValue": "15:30"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_high_temperature.png",
      "description": "高温/温度计图标，适合天气关怀、高温预警和风险提醒场景。"
    }
  ]
}

